            out.append('    ' * (indent - 1) + f"elif {m_elif.group(1)}:")
            continue

        out.append('    ' * indent + stripped)

    final_code = '\n'.join(out)

    try:
        exec(final_code, {"math": math, "print": print})
    except Exception as e:
        sys.stderr.write(f"error: {e}\n")

def main():
    args = sys.argv[1:]
    if not args:
        if sys.stdin.isatty():
            print_version()
            while True:
                try:
                    line = input("> ")
                    if line: transpile_and_run(line)
                except EOFError:
                    break
        else:
            transpile_and_run(sys.stdin.read(), is_expr=False)
        sys.exit(0)

